use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|s| s.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "open" {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(parts[1]) {
                println("error: duplicate account")
            } else {
                acc.insert(parts[1], amt)
                println("ok")
            }
        } else if cmd == "balance" {
            if acc.contains_key(parts[1]) {
                println("${acc.get(parts[1]).unwrap_or(0)}")
            } else {
                println("error: unknown account ${parts[1]}")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(parts[1]) {
                println("error: unknown account ${parts[1]}")
            } else {
                let b: int = acc.get(parts[1]).unwrap_or(0)
                if cmd == "deposit" {
                    acc.insert(parts[1], b + amt)
                    println("ok")
                } else if b < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(parts[1], b - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" {
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(parts[1]) {
                println("error: unknown account ${parts[1]}")
            } else if !acc.contains_key(parts[2]) {
                println("error: unknown account ${parts[2]}")
            } else if parts[1] == parts[2] {
                println("error: same account")
            } else {
                let fb: int = acc.get(parts[1]).unwrap_or(0)
                let tb: int = acc.get(parts[2]).unwrap_or(0)
                if fb < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(parts[1], fb - amt)
                    acc.insert(parts[2], tb + amt)
                    println("ok")
                }
            }
        }
    }
    let mut names: Vec<string> = []
    for k in acc.keys() {
        names.push(k)
    }
    names.sort()
    for n in names {
        println("${n} ${acc.get(n).unwrap_or(0)}")
    }
}

